mapper.select:
select DISTINCT M.APPLICATIONID, M.MENUID, M.MENUNAME, M.MENUNO, M.PARENTMENUID, M.MNUSYSTEM, M.MENUPROGRAM, M.MENUPIC, M.MENUORDER,M.ISBLANK from cf_menu_role mr inner join cf_menu m on mr.MenuId=m.MenuId where m.IsVisible=1
and mr.RoleID=#{roleId}
and ( m.MENUDESC is null or m.MENUDESC not in
#{id}
)
order by m.MenuOrder

select u.userid,u.applicationid,u.username,u.isanonymous,u.lastactivitydate,u.userpwd
from cf_users u
where u.UserName = #{UserLoginId}

select distinct info.USERID DGUSERID,info.USERID ID,r.XM NAME,zz.DZZDM dpid,zz.DZZMC dpname from CF_USERS info inner join VM_RYJBXX r on info.USERID=r.rybm inner join ZZ_ZZQKXX zz on r.SZDZBDM=zz.DZZDM where 1=1
and r.szdzbdm like concat('%',#{dpid},'%')
and zz.DZZMC =#{dzzmc}
and r.XM=#{username}

select count(1) from CF_MENU_ROLE mr
inner join CF_USERROLES ru on mr.ROLEID = ru.ROLEID
inner join CF_USERS u on ru.USERID = u.USERID
inner join CF_MENU m on mr.MENUID=m.MENUID
where 1=1


        #{ item }




    and u.USERNAME = #{ userName }



    and ru.ROLEID = #{ roleId }


    and (
    m.MENUDESC is null or m.MENUDESC not in

        #{id}

    )

        select u.* from CF_USERS u
inner join VM_RYJBXX i on u.USERID = i.RYBM
where i.XM= #{ name }

select distinct ry.rybm as "userCode",u.USERNAME as "mobile",ry.SZDZBDM as "dzzdm" from VM_RYJBXX ry inner join CF_USERS u on u.USERID=ry.RYBM where 1=1
and u.USERNAME in
#{mobile}

update.foreach:
insert into cf_users (USERID, APPLICATIONID, USERNAME, ISANONYMOUS, LASTACTIVITYDATE, USERPWD, FORCELOGINOUT)
select ry.rybm,'f0c4fa7f9f3c4fb6bd56aac608b7ad3f',#{user.mobile,jdbcType=VARCHAR},1,null,'D6FB6D8741F9AF9E7BC1C39E79D73944',null
from VM_RYJBXX ry
left join cf_users u on ry.rybm=u.userid
where ry.rybm=#{user.userCode,jdbcType=VARCHAR} and u.userid is null;

UPDATE cf_users T

    T.USERNAME = #{user.mobile,jdbcType=VARCHAR}

WHERE
T.USERID = #{user.userCode,jdbcType=VARCHAR}

mapper.select:
select u.USERID,u.LASTACTIVITYDATE,u.ISANONYMOUS,v.XM,u.USERNAME,z.DZZMC from CF_USERS u inner join VM_RYJBXX v on u.USERID = v.RYBM inner join ZZ_ZZQKXX z on v.SZDZBDM = z.DZZDM where u.USERNAME is not null and u.LASTACTIVITYDATE > #{ beforeTime }
and v.XM like concat('%',#{userName},'%')
order by u.LASTACTIVITYDATE desc
